import os

@test("save and load")
def _():
    save_scores("scores_a.txt", {"Grace": 88, "Ada": 95, "Linus Torvalds": 70})
    with open("scores_a.txt", encoding="utf-8") as f:
        check_eq(f.read(), "Ada,95\nGrace,88\nLinus Torvalds,70\n")
    check_eq(load_scores("scores_a.txt"), {"Ada": 95, "Grace": 88, "Linus Torvalds": 70})

@test("messy files")
def _():
    with open("scores_b.txt", "w", encoding="utf-8") as f:
        f.write(" Ada , 95 \n\njust text\nGrace,abc\nBob,-3\nToo,many,commas\n")
    check_eq(load_scores("scores_b.txt"), {"Ada": 95, "Bob": -3})

@test("missing file and appending")
def _():
    if os.path.exists("scores_c.txt"):
        os.remove("scores_c.txt")
    check_eq(load_scores("scores_c.txt"), {})
    add_score("scores_c.txt", "Ada", 1)
    add_score("scores_c.txt", "Ada", 2)
    check_eq(load_scores("scores_c.txt"), {"Ada": 2})

